import React, { useState, useEffect, useRef } from "react";
import {
  motion,
  AnimatePresence,
  useInView,
  useMotionValue,
  useSpring,
  useTransform,
} from "framer-motion";
import {
  Zap,
  Target,
  Trophy,
  Award,
  Flame,
  TrendingUp,
  ArrowUpRight,
  ChevronRight,
  Leaf,
  Droplets,
  BatteryCharging,
  CheckCircle2,
  Clock,
  UploadCloud,
} from "lucide-react";
import { MOCK_USER, MOCK_MISSIONS, MOCK_LOGS } from "../lib/mockData";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";
import { toast } from "react-hot-toast";

/* ---- ANIMATED COUNTER ---- */
function Counter({ from = 0, to, suffix = "", prefix = "" }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true });
  const val = useMotionValue(from);
  const smooth = useSpring(val, { stiffness: 55, damping: 16, mass: 0.9 });
  const [display, setDisplay] = useState(from);
  useEffect(() => {
    if (inView) val.set(to);
  }, [inView, to]);
  useEffect(
    () => smooth.on("change", (v) => setDisplay(Math.floor(v))),
    [smooth],
  );
  return (
    <span ref={ref} className="stat-number">
      {prefix}
      {display.toLocaleString()}
      {suffix}
    </span>
  );
}

/* ---- TYPEWRITER ---- */
function Typewriter({ text, delay = 0 }) {
  const [displayed, setDisplayed] = useState("");
  const [done, setDone] = useState(false);
  useEffect(() => {
    let i = 0;
    const t = setTimeout(() => {
      const iv = setInterval(() => {
        i++;
        setDisplayed(text.slice(0, i));
        if (i >= text.length) {
          clearInterval(iv);
          setDone(true);
        }
      }, 55);
      return () => clearInterval(iv);
    }, delay);
    return () => clearTimeout(t);
  }, [text, delay]);
  return (
    <span>
      {displayed}
      {!done && <span className="typing-cursor" />}
    </span>
  );
}

/* ---- 3D TILT CARD ---- */
function TiltCard({ children, className }) {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const mouseXSpring = useSpring(x);
  const mouseYSpring = useSpring(y);

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  const handleMouseMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    x.set(mouseX / width - 0.5);
    y.set(mouseY / height - 0.5);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
      className={className}
    >
      <div style={{ transform: "translateZ(30px)" }} className="h-full w-full">
        {children}
      </div>
    </motion.div>
  );
}

/* ---- CHART TOOLTIP ---- */
const ChartTip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
